 while av:
  xs=[i for i in range(n) if av>>i&1];x=min(xs,key=lambda i: (G[i]&av).bit_count());b=1<<x;s|=b;av &=~(G[x]|b)
 best=s.bit_count(); nodes=0; start=time.process_time(); deadline=start+secs
 def color(P):
  rem=P; order=[]; bounds=[]; c=0
  while rem:
   c+=1; avail=rem
   while avail:
    # choose based on original graph high degree or complement low degree
    if mode==0:
     x=max((i for i in range(n) if avail>>i&1), key=lambda i:(G[i]&P).bit_count())
    elif mode==1:
     x=min((i for i in range(n) if avail>>i&1), key=lambda i:(A[i]&P).bit_count())
    else:
     x=(avail&-avail).bit_length()-1
    b=1<<x;order.append(x);bounds.append(c);rem &=~b;avail &=~(b|A[x])
  return order,bounds
 def expand(P,dep):
  nonlocal best,nodes
  nodes+=1
  if nodes%1024==0 and time.process_time()>deadline:return
  if not P:
   if dep>best:best=dep
   return
  order,bounds=color(P)
  for i in range(len(order)-1,-1,-1):
   if dep+bounds[i]<=best:return
   x=order[i];b=1<<x
   Q=P&A[x]
   if Q:expand(Q,dep+1)
   elif dep+1>best:best=dep+1
   P &=~b
   if nodes%1024==0 and time.process_time()>deadline:return
 expand(full,0)
 return best,nodes,time.process_time()-start
