   mind=n+1; cand=[];xx=avail
   while xx:
    b=xx&-xx;x=b.bit_length()-1;d=(G[x]&avail).bit_count()
    if d<mind:mind=d;cand=[x]
    elif d<=mind+alpha:cand.append(x)
    xx-=b
   x=rng.choice(cand);b=1<<x;chosen|=b;avail &=~(G[x]|b)
  return chosen
